(31, 'RAM Kingston Fury Beast ', 12, 9, 15, 'Hãng sản xuất: Kingston\r\nTình trạng: Mới\r\nBảo hành: 36 tháng\r\nMàu sắc: Đen', 890000, '4826cf3649.webp', 0),
(32, 'Ram GIGABYTE Aorus ', 12, 9, 16, 'AORUS RGB Memory RAM\r\nThiết kế tiêu chuẩn, độ bền kinh ngạc và tương thích hoàn hảo trên hầu hết các dòng main máy tính có trên thị trương như Mainboard Intel 100 Series,Intel 200 Series,Intel 300 Series,Intel 400 Series,Intel X299 Series trên thị trường.\r\n\r\n', 1990000, '9102bf0e0b.webp', 1),
(33, 'RAM Kingston Fury Beast ', 12, 9, 15, 'Hãng sản xuất: Kingston\r\nTình trạng: Mới\r\nBảo hành: 36 tháng\r\nMàu sắc: Đen', 890000, '828f6afb60.webp', 0),
(34, 'Ram GIGABYTE Aorus Memory', 15, 9, 16, ' RAM Gigabyte Aorus Memory 32GB (2x16GB) 5200 DDR5\r\nHiệu suất được đảm bảo\r\nRAM Gigabyte Aorus Memory 32GB DDR5 cung cấp tốc độ bộ nhớ DDR5-5200 đáng tin cậy và nhanh chóng, đồng thời mang đến trải nghiệm về XMP 3.0 mới nhất. Ngoài ra, bằng cách sử dụng vật liệu tổng hợp đồng nhôm với bộ tản nhiệt NanoCarbon, không gây tổn hại đến bộ nhớ trong quá trình ép xung.', 7450000, '7b6402f663.webp', 0),
(35, 'RAM Kingston Fury Beast RGB', 12, 9, 15, 'RAM Kingston Fury Beast RGB 64GB (2x32GB) bus 5600 DDR\r\nKingston Fury, model RAM vô cùng được ưa chuộng bởi game thủ hiện nay. Thiết kế bắt mắt, hiệu năng mạnh mẽ, giá tiền phải chăng là những gì mà kit RAM từ Kingston mang đến. Và hôm nay, Kingston Fury đem đến model mới nhất của mình là Beast với cái tên đầy đủ là Kingston Fury Beast RGB. ', 6990000, '3eb7632f34.webp', 0),
(36, 'Ổ Cứng SSD PNY CS900 120GB Sata3', 15, 8, 17, '', 490000, '5e87a84839.jpg', 0),
(37, 'Ổ cứng SSD Kingston NV2 250GB M.2 PCIe NVMe Gen4', 10, 8, 15, 'Ổ SSD Kingston NV2 250GB M.2 PCIe NVMe Gen4 là giải pháp lưu trữ có dung lượng lớn, với tốc độ đọc/ghi lên tới 3.000/1.300MB/giây, nhanh gấp 3 - 4 lần ổ SSD SATA và nhanh gấp 35 lần so với một ổ cứng truyền thống. Ổ NV2 tiêu tốn ít năng lượng hơn, tỏa ra nhiệt thấp hơn và có thời gian tải nhanh hơn. Nhờ hiệu năng hữu ích cùng thiết kế một mặt M.2 2280 (22x80mm), ổ NV2 trở thành phụ kiện lý tưởng cho các mẫu máy tính xách tay và hệ thống có kích thước mỏng với dung lượng hạn chế.', 990000, '42ddaafb8b.webp', 0),
(39, 'Ổ cứng SSD Kingston NV3 500GB M.2 PCIe NVMe Gen4', 12, 8, 15, '', 1590000, '0a6de83d7f.webp', 0),
(40, 'Loa Logitech G560', 12, 10, 9, 'Công nghệ LIGHTSYNC RGB kết hợp với Audio Visualizer\r\nÁnh sáng và màu sắc của loa Logitech G560 có thể đồng bộ với những gì diễn ra trên màn hình: giai điệu, âm thanh nhờ vào công nghệ Audio Visualizer mang lại cho bạn buổi trình diễn âm thanh với ánh sáng hoành tráng.', 3890000, '2299cde3ed.webp', 0),
(41, 'Micro Kingston HyperX QuadCast S White', 12, 23, 18, 'Microphone Kingston HyperX QuadCast S White là một microphone tích hợp đầy đủ tính năng, phù hợp cho streamer hay podcaster đang tìm kiếm một chiếc micro có chất lượng thu âm tốt. Thiết kế microphone đẹp, tiện lợi với những tính năng tích hợp đi kèm để giúp âm thanh thu vào trong trẻo hơn. Microphone dòng QuadCase S đều được trang bị hệ thống đèn RGB để cung cấp hiệu ứng ánh sáng sống động.', 3290000, '9ff74228a2.webp', 0),
(42, 'Webcam Logitech Brio 4k', 12, 24, 9, 'Logitech Brio 4k dòng webcam nâng tầm cho trải nghiệm với video ultra 4K HD, tự động điều chỉnh để giúp bạn có hình ảnh chuyên nghiệp ở mọi điều kiện ánh sáng. Đặc biệt, với công nghệ xử lý âm thanh hiện đại hỗ trợ cho mọi cuộc trò chuyện chất lượng âm thanh tự nhiên và rõ ràng.\r\n\r\nTối ưu cho các cuộc họ', 4590000, '9f8ca5ba1e.webp', 0),
(43, 'Màn hình MSI PRO', 12, 11, 3, '', 2490000, '3cb3b21dfe.webp', 0),
(44, 'Màn hình Lenovo L24i-4A 24\" IPS 100Hz', 0, 11, 4, 'Màn hình Lenovo L24i-4A 24\" IPS 100Hz là một sản phẩm vừa có ngoại hình bắt mắt vừa có hiệu năng tân tiến. Màn hình được trang bị những công nghệ hiện đại nhất mang đến cho người dùng các hình ảnh sắc nét song song đó là những công nghệ giúp bảo vệ mắt tốt nhất.', 2490000, 'fdf985ed40.webp', 0),
(45, 'Màn hình Samsung Odyssey G6', 2, 11, 20, 'Samsung Odyssey G6 LS27DG602 là một trong những màn hình gaming cao cấp nhất hiện nay, được trang bị những công nghệ hàng đầu để mang đến trải nghiệm chơi game đỉnh cao. Với tấm nền OLED tuyệt đẹp, tần số quét 360Hz siêu mượt và thời gian phản hồi cực nhanh, Odyssey G6 hứa hẹn đem đến cho người dùng những trải nghiệm chơi game, làm việc trọn vẹn nhất.', 18490000, 'b3593f1232.webp', 0),
(46, 'Màn hình Philips 27E2N1500', 5, 11, 21, 'Philips 27E2N1500 27” IPS 2K 120Hz chính là lựa chọn hoàn hảo dành cho bạn! Với những ưu điểm vượt trội về tốc độ làm mới, độ phân giải và công nghệ hiển thị, chiếc màn hình này sẽ đưa bạn đến một thế giới hình ảnh sống động và mượt mà chưa từng có. Với tốc độ làm mới 120Hz, Philips 27E2N1500 mang đến trải nghiệm hình ảnh mượt mà, sống động, đặc biệt là khi chơi game hoặc xem video hành động. Tốc độ làm mới cao giúp giảm thiểu hiện tượng giật hình, xé hình, mang lại những khung hình mượt mà và liền mạch, khiến bạn hoàn toàn chìm đắm trong thế giới ảo. \r\n\r\n', 3790000, '649259823a.webp', 0),
(47, 'Màn hình E-DRA EGM27Q100PR', 15, 11, 22, 'Chất lượng hiển thị ấn tượng, sắc nét và sống động\r\nE-DRA EGM27Q100PR 27” IPS 2K 100Hz sở hữu kích thước 27 inch và độ phân giải 2K - QHD (2560x1440), mang đến hình ảnh sắc nét, chi tiết, không bị mờ nhòe. Tấm nền Fast IPS chất lượng A+ cho màu sắc tươi sáng, góc nhìn rộng 178 độ, không bị sai lệch màu. Chỉ số màu sắc 16.7 triệu màu, tương đương 97% sRGB và 72% NTSC, tái tạo màu sắc siêu chân thực, sống động. Độ sáng 280cd/m2 đảm bảo khả năng hiển thị tốt trong môi trường ánh sáng trong nhà.\r\n\r\n', 3690000, '3b14abbf1b.webp', 0),
(48, 'Chuột Razer Basilisk V3 Pro ', 9, 12, 24, 'Nâng tầm trải nghiệm chơi game với Razer Basilisk V3 Pro 35K – chuột chơi game không dây RGB công thái học với khả năng tùy chỉnh và công nghệ tiên tiến nhất. Với cảm biến chính xác hoàn hảo và con lăn chuột với các tùy chọn cấu hình chuyên sâu, chơi game theo cách của bạn chưa bao giờ thú vị đến thế.', 4490000, '4ad600cf60.webp', 1),
(49, 'Chuột Corsair Sabre RGB Pro Wireless ', 22, 12, 25, 'Corsair Sabre RGB Pro Wireless đã được thiết kế và thử nghiệm bởi các game thủ chuyên nghiệp hàng đầu. Trọng lượng siêu nhẹ, chỉ 79g và được trang bị công nghệ điều khiển không dây sử dụng vô tuyến độc quyền Corsair Slipstream.', 2290000, 'a287e61158.webp', 0),
(50, 'Chuột Pulsar có dây X2H Medium Black', 11, 12, 26, 'Pulsar X2H Wired Medium là một chiếc chuột gaming được thiết kế để mang đến trải nghiệm chơi game thoải mái và hiệu quả. Với thiết kế nhỏ gọn, trọng lượng siêu nhẹ và cảm biến chính xác, chiếc chuột này là lựa chọn hoàn hảo cho các game thủ chuyên nghiệp và nghiệp dư.\r\n\r\n', 1390000, '78f5d7b85b.webp', 0),
(51, 'Bàn phím AKKO MU01 Mountain Seclusion Rosewood', 11, 16, 23, 'AKKO MU01 Mountain Seclusion: Phiên bản giới hạn được lấy cảm hứng từ những bức tranh thủy mặc các ngọn núi miền sơn cước của Trung Quốc. Thiết kế sang trọng vỏ phím được làm bằng chất liệu đặt biệt từ gỗ óc chó cao cấp. Keycap là bài thơ hoàn chỉnh “Autumn Twilight in the Mountain Abode” – (chạng vạng thu trên núi).', 2890000, 'a371a2ef13.png', 0),
(52, 'Bàn phím cơ DareU A98 Pro TM Red Wave Dream', 25, 16, 27, 'DareU A98 Pro TM Red Wave Dream switch một trong những sản phẩm nổi bật trong phân khúc bàn phím cơ gaming tầm trung được nhà DareU giới thiệu đến người dùng, đặc biệt với thiết kế bề ngoài rất thu hút sự chú ý của các gamer và những ai yêu thích custom theo sở thích của mình thì có thể lựa DareU A98 Pro TM Red Wave Dream switch để có được những trải nghiệm rất ưng ý nhé. ', 1390000, '87f5966e27.webp', 1),
(53, 'Bàn phím Corsair K65 Plus Wireless', 8, 16, 25, '', 3890000, 'a9109672a7.webp', 0),
(54, 'Bàn phím Bluetooth Rapoo Ralemo Pre 5 RA', 12, 16, 28, 'Bàn phím cơ Rapoo RALEMO PRE 5 RA là một sản phẩm độc đáo, kết hợp giữa thiết kế cổ điển với các tính năng hiện đại, mang đến trải nghiệm gõ phím tuyệt vời và phong cách làm việc độc đáo. Với khả năng kết nối đa dạng, keycap PBT bền bỉ và đèn nền LED rực rỡ, Rapoo RALEMO PRE 5 RA là sự lựa chọn hoàn hảo cho những người yêu thích sự hoài cổ nhưng vẫn đòi hỏi hiệu suất và tính năng hiện đại.', 589998, 'a7755d88f8.webp', 0);

